# AUTO-GENERATED BY IceWright {{engine_version}} · 重生成会检测本地修改而非静默覆盖（加 ICEWRIGHT-CUSTOM 标记则完全交给定制层）
"""HTTP 层：入参校验与响应模型，业务逻辑一律下沉到 service。

页面矩阵：/ 调试聊天页（必含）、/admin 开发后台（必含，只读契约与运行态）、
/console 业务人员后台（workspace.business_console=true 时生成，否则 404）。
"""
import json
from pathlib import Path
from typing import Any, Literal

from fastapi import APIRouter, HTTPException
from fastapi.responses import FileResponse
from pydantic import BaseModel, Field

from app.config.settings import settings
from app.domain import i18n
from app.domain import rules as rule_engine
from app.service import chat as chat_service
from app.service import session as session_service

router = APIRouter()

STATIC_DIR = Path(__file__).resolve().parents[2] / "static"
DATA_DIR = Path(__file__).resolve().parents[1] / "data"


class ChatRequest(BaseModel):
    session_id: str = Field(min_length=1, max_length=128)
    message: str = Field(min_length=1, max_length=4000)
    language: Literal["zh", "en"] = "zh"


class ChatResponse(BaseModel):
    session_id: str
    reply: str
    matched_rules: list[str]
    language: str


class HealthResponse(BaseModel):
    project: str
    pack_ref: str
    redis: str
    languages: list[str]


@router.get("/", include_in_schema=False)
def home() -> FileResponse:
    return FileResponse(STATIC_DIR / "chat.html")


@router.get("/healthz", response_model=HealthResponse)
def healthz() -> HealthResponse:
    return HealthResponse(
        project=settings.project,
        pack_ref=settings.pack_ref,
        redis=session_service.redis_ping(),
        languages=sorted(i18n.MESSAGES),
    )


@router.post("/chat", response_model=ChatResponse)
def chat(req: ChatRequest) -> ChatResponse:
    return ChatResponse(**chat_service.answer(req.session_id, req.message, req.language))


def _read_data_json(name: str) -> list[dict]:
    path = DATA_DIR / name
    if not path.exists():
        return []
    payload = json.loads(path.read_text(encoding="utf-8"))
    key = name.removesuffix(".json")
    rows = payload.get(key, []) if isinstance(payload, dict) else payload
    return [r for r in rows if isinstance(r, dict)]


@router.get("/sessions/{session_id}")
def session_detail(session_id: str) -> dict[str, Any]:
    """会话槽位回显（调试页用）：只读 Redis 中的易失状态，不含业务数据。"""
    return {"session_id": session_id, "slots": session_service.load_slots(session_id)}


@router.get("/admin", include_in_schema=False)
def admin() -> FileResponse:
    return FileResponse(STATIC_DIR / "admin.html")


@router.get("/admin/overview")
def admin_overview() -> dict[str, Any]:
    """开发后台只读总览：运行态 + 规则/技能/接口契约（编译进项目的数据文件）。"""
    return {
        "project": settings.project,
        "pack_ref": settings.pack_ref,
        "redis": session_service.redis_ping(),
        "languages": sorted(i18n.MESSAGES),
        "model_configured": bool(
            settings.model_base_url and settings.model_name and settings.model_api_key
        ),
        "core_mode": settings.core_mode,
        "business_console": settings.business_console,
        "rules": rule_engine.load_rules(),
        "skills": _read_data_json("skills.json"),
        "apis": _read_data_json("apis.json"),
    }


def _require_console() -> None:
    if not settings.business_console:
        raise HTTPException(status_code=404, detail="业务后台未开启")


@router.get("/console", include_in_schema=False)
def console() -> FileResponse:
    _require_console()
    return FileResponse(STATIC_DIR / "console.html")


@router.get("/console/sessions")
def console_sessions() -> list[dict[str, Any]]:
    """业务后台会话列表：仅返回被规则打标的会话（session_id + 规则 id + 轮数）。"""
    _require_console()
    rows = []
    for item in session_service.list_sessions():
        slots = item["slots"]
        if slots.get("flagged"):
            rows.append(
                {
                    "session_id": item["session_id"],
                    "flagged": slots["flagged"],
                    "turns": slots.get("turns", 0),
                }
            )
    return rows
